    Section HeadCells.
      Variables (b1 actx idv : Z) (hdq qbytes : Z).
      Hypothesis HDR1 : ltac2:(zQ "c0!kk3!jjf!li2!li8!lie!jl6!hi9!lj4!lja!lk0!koc!hrc@4$a$6?2m1@2$b?1U-h0@3$1$0@1$3@1$4+3@3$1$0@1$3@1$4?2b1@3$1$0@1$7@1$2Z@3$1$0@1$8@1$2?4size@3$1$0@1$9@1$2?4actx@1$5$0").
      Hypothesis UW1 : ltac2:(zQ "70!kk3!jjf!jl6!hi9!lk0!koc!li2@4$5$3?2m1?1U@3$1$0@1$4@1$6?3idv@1$2$0").
      Hypothesis FLG1 : ltac2:(zQ "a0!kk3!jjf!li8!lie!jl6!hi9!hs3!lj4!koc!li2@4$8$5?2m1$6@3$1$0@1$2@1$3+1@3$1$0@1$2@1$3Z@3$1$0@1$7@1$9Z@1$4$0").
      Hypothesis IA1 : ltac2:(zQ "10!lo5@1$0?2m1").
      Hypothesis SHF1 : ltac2:(zQ "a0!lq8!lr2!hi9!ij8!ii5!lr9!mga!lie!kp8!mj0@4$6$2?2m1@1$4?1U@3$0@1$9@1$1#8@1$7$5@1$8@1$3?4size").
      Hypothesis TQ1 : rw_cells asegs m1 (TH + OT_TQ) [C8 (wz k); C8 (wz hdq); C8 (wz LA); C8 (wz qbytes)].
      Hypothesis LC1 : k <> 0 -> rw_cells asegs m1 LA [C8 (wz 0)] /\ rw_cells asegs m1 (LA + 16) [C8 (wz kBatchCount)].
      Hypothesis INST0 : rw_cells asegs m (AINST + OI_SPACEBEG) [C8 (wz sb)].

      Lemma head_cells2 :
           rw_cells asegs m2 (U + -16) [C1 (b8 3); C1 (b8 b1); C2 (wz 0); C4 (wz size); C8 (wz actx)]
        /\ rw_cells asegs m2 U [C8 (wz idv)]
        /\ rw_cells asegs m2 AIAINIT [C1 (b8 1); C1 (b8 0); C2 (wz 0)] /\ ia_after m2
        /\ u8arr asegs m2 (sh U) (repeat (b8 kAsanHeapFreeMagic) (Z.to_nat (nsh size)))
        /\ rw_cells asegs m2 (TH + OT_TQ) [C8 (wz k); C8 (wz hdq); C8 (wz LA); C8 (wz qbytes)]
        /\ (k <> 0 -> rw_cells asegs m2 LA [C8 (wz 0)])
